// ─── Дополнения по аудиту полноты (26.11.2026): входные данные текстом, тексты вместо схем, разборы ───
const ins = (l: AccLesson, after: string, ...ps: ReturnType<typeof p>[]) => {
  const i = l.content.paragraphs.findIndex(x => x.id === after)
  if (i < 0) throw new Error(`ins: нет абзаца ${after} в ${l.key}`)
  l.content.paragraphs.splice(i + 1, 0, ...ps)
}

ins(L1, 'need',
  p('data-text', '**Входные данные — текстом (лист «Сотрудники», A–E; вымышленные).**\n— E01 — Иванов Иван Иванович — Альфа — 0,25 — ОСН\n— E01 — Иванов Иван Иванович — Бета — 1 — СОВ\n— E02 — Петров Петр Петрович — Альфа — 0,25 — СОВ\n— E02 — Петров Петр Петрович — Бета — 0,5 — ОСН\n— E03 — Сидорова Анна Игоревна — Альфа — 0,5 — ДЕКРЕТ\n— E04 — Ким Олег Сергеевич — Гамма — 1 — ОСН\n— E05 — Орлова Мария Сергеевна — Гамма — 0,5 — (пусто)\n— E05 — Орлова Мария Сергеевна — Бета — 0,5 — (пусто)\n— E06 — Волков Артем Иванович — Альфа — 0,25 — СОВ\n— E07 — Иванов Иван Иванович — Гамма — 0,5 — ОСН\nЗаголовки F–K: «Записей на ID», «ОСН + ДЕКРЕТ на ID», «Итоговый статус», «Учесть человека», «Первый ID», «Нерешенный ID». Обратите внимание: E01 и E07 — одно ФИО, но разные ID: это разные люди, считаются по ID.'),
)
